.iconButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border: 0;
  padding: 0;
  cursor: pointer;
  transition:
    background-color var(--dur) var(--ease),
    color var(--dur) var(--ease),
    box-shadow var(--dur) var(--ease),
    transform var(--dur) var(--ease);
}

.iconButton:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

/* Match Button sizes exactly so an IconButton (chevron) sits flush
   against a Button in a split-button ButtonGroup. Previously the sizes
   were hard-coded (28/36/44) while Button used --control-h-* (32/40/48),
   leaving a 4 px height mismatch in the "Send invoice" split button. */
.sm {
  width: var(--button-height-sm, var(--control-h-sm));
  height: var(--button-height-sm, var(--control-h-sm));
  border-radius: var(--icon-button-radius, var(--r-xs));
}

.md {
  width: var(--button-height-md, var(--control-h-md));
  height: var(--button-height-md, var(--control-h-md));
  border-radius: var(--icon-button-radius, var(--r-sm));
}

.lg {
  width: var(--button-height-lg, var(--control-h-lg));
  height: var(--button-height-lg, var(--control-h-lg));
  border-radius: var(--icon-button-radius, var(--r-md));
}

/* Ghost: the reference bell / close button. Muted ink, accent on hover. */
.ghost {
  color: var(--ink-muted);
  background: transparent;
}

.ghost:hover:not(:disabled) {
  color: var(--ink-brand);
  background: var(--wash-subtle);
}

.ghost:active:not(:disabled),
.ghost[aria-pressed="true"] {
  color: var(--ink-brand);
  background: var(--wash-active);
}

.secondary {
  color: var(--ink-heading);
  background: rgba(var(--rgb-white), 0.5);
  -webkit-backdrop-filter: var(--blur-callout);
  backdrop-filter: var(--blur-callout);
  box-shadow: inset 0 0 0 1px var(--glass-edge-strong), var(--shadow-specular), 0 1px 3px rgba(var(--rgb-contact), 0.08);
}

.secondary:hover:not(:disabled) {
  background: rgba(var(--rgb-white), 0.72);
  transform: translateY(-1px);
}

.secondary:active:not(:disabled) {
  transform: translateY(0);
  background: rgba(var(--rgb-white), 0.58);
}

:global([data-surface="solid"]) .secondary {
  background: var(--surface-solid);
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  box-shadow: var(--shadow-control);
}

.primary {
  color: var(--ink-inverse);
  background: var(--brand-gradient);
  box-shadow: var(--glow-md), var(--shadow-specular-dark);
}

.primary:hover:not(:disabled) {
  box-shadow: var(--glow-md-hover), var(--shadow-specular-dark);
  transform: translateY(-1px);
}

.primary:active:not(:disabled) {
  transform: translateY(0);
  box-shadow: var(--glow-sm);
}

.danger {
  color: var(--danger-ink);
  background: transparent;
}

.danger:hover:not(:disabled) {
  background: var(--danger-fill);
}

.danger:active:not(:disabled) {
  background: rgba(var(--rgb-danger), 0.14);
}

.iconButton:disabled:not(.loading) {
  cursor: not-allowed;
  color: var(--ink-disabled);
  background: transparent;
  box-shadow: none;
  transform: none;
}

.primary:disabled:not(.loading),
.secondary:disabled:not(.loading) {
  background: rgba(var(--rgb-brand-deep), 0.06);
}

.loading {
  cursor: progress;
}

import type { ComponentPropsWithRef, ReactNode } from "react";
import { cx } from "../_internal/cx";
import { Slot } from "../_internal/slot";
import { Spinner } from "../Spinner/Spinner";
import styles from "./IconButton.module.css";

export type IconButtonProps = Omit<ComponentPropsWithRef<"button">, "aria-label"> & {
  /** Required: an icon-only control has no other accessible name. */
  label: string;
  icon: ReactNode;
  variant?: "ghost" | "secondary" | "primary" | "danger";
  size?: "sm" | "md" | "lg";
  loading?: boolean;
  /** Makes it a toggle button (aria-pressed). */
  pressed?: boolean;
  /** Render the single child element (a Next <Link>, an <a>) with the icon button's look; pass the icon inside the child. */
  asChild?: boolean;
  children?: ReactNode;
};

export function IconButton({
  label,
  icon,
  variant = "ghost",
  size = "md",
  loading,
  pressed,
  disabled,
  className,
  type = "button",
  title,
  asChild,
  children,
  ...rest
}: IconButtonProps) {
  const cls = cx(styles.iconButton, styles[variant], styles[size], loading && styles.loading, className);
  if (asChild) {
    return (
      <Slot aria-label={label} title={title ?? label} className={cls} data-slot="icon-button" data-variant={variant} data-size={size} {...(rest as Record<string, unknown>)}>
        {children}
      </Slot>
    );
  }
  return (
    <button
      type={type}
      aria-label={label}
      title={title ?? label}
      aria-pressed={pressed}
      aria-busy={loading || undefined}
      disabled={disabled || loading}
      className={cls}
      data-slot="icon-button"
      data-variant={variant}
      data-size={size}
      {...rest}
    >
      {loading ? <Spinner size={size === "sm" ? 13 : 15} tone="current" /> : icon}
    </button>
  );
}
